@Component("returnRequest-handler")
@ProcessingGroup("returnRequest-processing-group")
public class ReturnRequestEventHandler {
	
	// core constructor
	ReturnRequestEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateReturnRequestEvent
     */
    @EventHandler
    public void handle( CreateReturnRequestEvent event) {
        entityManager.persist(new ReturnRequest(event.getReturnRequestId(), event.getReturnNumber(), event.getCreatedAt(), event.getRefundAmount(), event.getOrder(), event.getItems(), event.getRefund(), event.getShipment(), event.getStatus()));
    }

    /*
     * @param	event UpdateReturnRequestEvent
     */
    @EventHandler
    public ReturnRequest handle( UpdateReturnRequestEvent event) {
    	entityManager.merge(new ReturnRequest(event.getReturnRequestId(), event.getReturnNumber(), event.getCreatedAt(), event.getRefundAmount(), event.getOrder(), event.getItems(), event.getRefund(), event.getShipment(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteReturnRequestEvent
     */
    @EventHandler
    public void on( DeleteReturnRequestEvent event) {
    	ReturnRequest entity = new ReturnRequest();
   
    	// ------------------------------------------
    	// apply the ReturnRequestId
    	// ------------------------------------------
    	entity.setReturnRequestId( event.getReturnRequestId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ReturnRequestRepository returnRequestEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ReturnRequestEventHandler.class.getName());

}
